script:
const banner = $(root_element).find("#user-profile-banner");
if (!banner.length) return;

const email = frappe.session?.user_email || "";
const avatarHtml = frappe.avatar(email || frappe.session?.user || "");

// Insert avatar into wrapper
banner.find(".avatar-wrapper").html(avatarHtml);

// Set email
banner.find(".email").text(email);

// Fetch user's full name
frappe.db
	.get_value("User", frappe.session.user, "full_name")
	.then(({ message }) => {
		const name = message?.full_name || "Welcome";
		banner.find(".full-name").text(`Welcome ${name}`);
	})
	.catch(() => {
		banner.find(".full-name").text("Welcome");
	});

style:
/* Container */
#user-profile-banner.profile-banner {
	width: 100%;
	max-width: 1100px;
	margin: 0 auto;
	font-family: var(
		--font-family,
		"Inter",
		system-ui,
		-apple-system,
		"Segoe UI",
		Roboto,
		"Helvetica Neue",
		Arial
	);
	color: var(--text-color, #222);
	box-sizing: border-box;
	position: relative;
}

/* Banner image area */
.banner-wrapper {
	position: relative;
	width: 100%;
	height: 260px;
	border-radius: var(--border-radius-lg, 12px);
	background: var(--card-bg, #f5f5f5);
}

.banner-wrapper .banner-img {
	width: 100%;
	height: 100%;
	object-fit: cover;
	object-position: center;
	display: block;
}

/* Avatar positioning */
.avatar-wrapper {
	position: absolute;
	bottom: -60px;
	left: 50px;
	display: flex;
	align-items: center;
	justify-content: flex-start;
}

.avatar-wrapper .avatar,
.avatar-wrapper .avatar-frame,
.avatar-wrapper img {
	width: 140px;
	height: 140px;
	border-radius: 50%;
	box-shadow: 0 6px 18px rgba(0, 0, 0, 0.12);
	object-fit: cover;
}

/* Info section*/
.info {
	padding-left: 220px;
	padding-top: 5px;
}

.full-name {
	font-size: 1.5rem;
	font-weight: 600;
}

.email {
	font-size: 0.95rem;
	font-weight: 400;
	color: var(--text-muted, #6c6c6c);
}

/* Responsive adjustments */
@media (max-width: 768px) {
	.banner-wrapper {
		height: 200px;
	}

	.avatar-wrapper {
		bottom: -60px;
		left: 30px;
	}

	.avatar-wrapper .avatar,
	.avatar-wrapper .avatar-frame,
	.avatar-wrapper img {
		width: 110px;
		height: 110px;
	}

	.info {
		padding-left: 160px;
		padding-top: 5px;
	}

	.full-name {
		font-size: 1.2rem;
	}
}

@media (max-width: 480px) {
	.banner-wrapper {
		height: 160px;
	}

	.avatar-wrapper {
		bottom: -45px;
		left: 20px;
	}

	.avatar-wrapper .avatar,
	.avatar-wrapper .avatar-frame,
	.avatar-wrapper img {
		width: 90px;
		height: 90px;
		border-width: 3px;
	}

	.info {
		padding-left: 130px;
		padding-top: 5px;
	}

	.full-name {
		font-size: 1.1rem;
	}

	.email {
		font-size: 0.85rem;
	}
}
